// The bash course's live-exercise helpers (js/shellex.js): the "re-run on new data" anti-cheat, outcome options
// generated by the engine, and the engine's line completion for the terminal's Tab. Run: node --test tests/
import test from 'node:test';
import assert from 'node:assert/strict';
import { UNITS } from '../js/content/bash/index.js';
import { freshShell, replay, gradeShellType, readsOutput, cheatLine, outcomeOptions, outcomeProblems, treeLines, gradeScript, runScript, scriptCommands, scriptReadsOutput, cheatScript } from '../js/shellex.js';
import { SCRIPT_FIXTURES } from './fixtures/script-exercises.mjs';
import { runOut, runCode, runErr } from '../js/content/shell-helpers.js';
import { buildShell } from '../js/shell.js';
import { printedNumber, lineCount, listOf } from '../js/content/bash/helpers.js';

const byId = (id) => {
  for (const u of UNITS) for (const l of [...u.lessons, ...u.challenges]) for (const ex of l.exercises) if (ex.id === id) return ex;
  throw new Error(`no exercise ${id}`);
};
// play an exercise the way the lesson player does: type lines into the live shell, then grade
const play = (ex, lines) => gradeShellType(ex, replay(ex.setup, lines), lines);
// what the learner saw on the screen after running a command on the live data
const seen = (ex, cmd) => replay(ex.setup, [cmd]).lastOut.trim();

test('anti-cheat: echo with the answer fails, a real command passes (wc -l)', () => {
  const ex = byId('rd3-type-lines');
  const answer = seen(ex, 'wc -l < access.log');        // the number the learner could copy
  assert.match(answer, /^\d+$/);
  const cheat = play(ex, [`echo ${answer}`]);
  assert.equal(cheat.live, true, 'echo passes on the data the learner sees...');
  assert.equal(cheat.variant, false, '...but not when replayed on the variant');
  assert.equal(cheat.ok, false);
  for (const real of [['wc -l access.log'], ['wc -l < access.log'], ['cat access.log | wc -l']]) assert.equal(play(ex, real).ok, true, real[0]);
});

test('anti-cheat: echo fails, a real pipeline passes (ls | wc -l)', () => {
  const ex = byId('pp2-type-count');
  const answer = seen(ex, 'ls photos | wc -l');
  assert.equal(play(ex, [`echo ${answer}`]).ok, false);
  assert.equal(play(ex, [`echo ${answer}`]).live, true);
  assert.equal(play(ex, ['ls photos | wc -l']).ok, true);
  assert.equal(play(ex, ['cd photos', 'ls | wc -l']).ok, true, 'any valid route, over several lines');
});

test('anti-cheat is a general mechanism: any exercise with setup + variant', () => {
  const files = (n) => (sh) => sh.setupFiles(Object.fromEntries(Array.from({ length: n }, (_, i) => [`docs/f${i}.txt`, 'x\n'])));
  const ex = { setup: files(3), variant: files(7), check: (sh) => printedNumber(sh, listOf(sh, 'docs').length) };
  assert.equal(play(ex, ['echo 3']).ok, false);
  assert.equal(play(ex, ['ls docs | wc -l']).ok, true);
  // without a variant only the live check counts
  assert.equal(play({ ...ex, variant: undefined }, ['echo 3']).ok, true);
  // a check that throws is a fail, never a crash
  assert.equal(play({ ...ex, check: () => { throw new Error('boom'); } }, ['ls']).ok, false);
  // readsOutput tells output checks from state checks
  assert.equal(readsOutput(ex, ['ls docs | wc -l']), true);
  assert.equal(readsOutput({ setup: files(1), check: (sh) => listOf(sh, '~').includes('new') }, ['mkdir new']), false);
  // the content test's hard-coded answer prints exactly the solution's output
  const sh = freshShell(files(1));
  sh.run(cheatLine("it's\n2 lines\n"));
  assert.equal(sh.lastOut, "it's\n2 lines\n");
});

test('every output-reading bash exercise rejects its own hard-coded answer', () => {
  let n = 0;
  for (const u of UNITS) for (const l of [...u.lessons, ...u.challenges]) for (const ex of l.exercises) {
    if (ex.type !== 'type') continue;
    const lines = ex.solution.split(/\n|&&|;/).map((s) => s.trim()).filter(Boolean);
    if (!readsOutput(ex, lines)) continue;
    n++;
    const cheat = cheatLine(replay(ex.setup, lines).lastOut);
    assert.equal(play(ex, [cheat]).ok, false, `${ex.id}: ${cheat}`);
    assert.equal(play(ex, lines).ok, true, `${ex.id}: the solution`);
  }
  assert.ok(n >= 10, `only ${n} output exercises`);
});

test('outcome options come from the engine: exactly one is right', () => {
  const ex = { setup: (sh) => sh.setupFiles({ 'todo.txt': 'milk\n', 'notes/': null }), command: 'mv todo.txt notes/', show: 'tree', distractors: [['cp todo.txt notes/'], ['mv todo.txt notes.txt'], ['cp todo.txt notes/']] };
  const { start, opts } = outcomeOptions(ex);
  assert.equal(opts.length, 3, 'a duplicate distractor is dropped');
  assert.equal(opts.filter((o) => o.ok).length, 1);
  assert.deepEqual(treeLines(start), ['~  (you are here)', '  notes/', '  todo.txt']);
  assert.deepEqual(opts[0].value.split('\n'), ['~  (you are here)', '  notes/', '    todo.txt']);
  assert.deepEqual(outcomeProblems(ex), ['distractor [cp todo.txt notes/] gives the same result as [cp todo.txt notes/]']);
  const out = { setup: (sh) => sh.setupFiles({ 'a.txt': '1\n2\n3\n' }), command: 'head -n 2 a.txt', show: 'output', distractors: [['tail -n 2 a.txt']] };
  assert.deepEqual(outcomeOptions(out).opts.map((o) => o.value), ['1\n2', '2\n3']);
  assert.deepEqual(outcomeProblems(out), []);
  assert.match(outcomeProblems({ ...out, distractors: [['cat nope.txt']] })[0], /fails/);
});

test('Tab completion from the engine: commands, paths, variables, quoting', () => {
  const sh = buildShell({ files: { 'notes/todo.txt': 'a', 'notes/ten.txt': 'b', 'my file.txt': 'm' } });
  assert.deepEqual(sh.complete('whoa'), { line: 'whoami ', options: ['whoami'] });
  assert.equal(sh.complete('ls no').line, 'ls notes/');
  assert.deepEqual(sh.complete('cat notes/t').options, ['notes/ten.txt', 'notes/todo.txt']);
  assert.equal(sh.complete('cat notes/to').line, 'cat notes/todo.txt ');
  assert.ok(sh.complete('ls | w').options.includes('wc'), 'after a pipe: a command');
  assert.equal(sh.complete('cat my').line, 'cat my\\ file.txt ');
  assert.equal(sh.complete('echo $HOM').line, 'echo $HOME ');
  assert.equal(sh.complete('cd ~/no').line, 'cd ~/notes/');
  assert.deepEqual(sh.complete('cat zzz'), { line: 'cat zzz', options: [] });
});

test('bash exercise ids are unique across lessons and puzzles; lineCount counts like wc -l', () => {
  const ids = new Set();
  for (const u of UNITS) for (const l of [...u.lessons, ...u.challenges]) for (const ex of l.exercises) { assert.ok(!ids.has(ex.id), ex.id); ids.add(ex.id); }
  assert.equal(lineCount(buildShell({ files: { a: '1\n2\n' } }), 'a'), 2);
});

/* ------------------------------------------------------------------ the script type */
const fx = (id) => SCRIPT_FIXTURES.find((e) => e.id === id);

test('script: the solution passes, the starter fails, on the setup and the variant', () => {
  const ex = fx('fx-script-backup');
  const sol = gradeScript(ex, ex.solution);
  assert.deepEqual([sol.ok, sol.live, sol.variant], [true, true, true]);
  assert.equal(runOut(sol.sh), 'Backed up 3 files');
  assert.deepEqual(listOf(sol.sh, 'backup'), ['ideas.txt', 'plan.txt', 'todo.txt']);
  const st = gradeScript(ex, ex.starter);
  assert.equal(st.ok, false);
  assert.equal(runOut(st.sh), 'Backed up 0 files');
  // another correct route: count the copies afterwards
  const other = '#!/bin/bash\nmkdir -p backup\ncp "$1"/*.txt backup/\necho "Backed up $(ls backup | wc -l) files"\n';
  assert.equal(gradeScript(ex, other).ok, true, 'any script that does the job passes');
});

test('script: a hard-coded answer passes the live data and fails the variant', () => {
  const ex = fx('fx-script-backup');
  const fake = '#!/bin/bash\nmkdir -p backup\ncp docs/*.txt backup/\necho "Backed up 3 files"\n';
  const g = gradeScript(ex, fake);
  assert.deepEqual([g.live, g.variant, g.ok], [true, false, false]);
  assert.equal(scriptReadsOutput(ex), true);
  assert.equal(gradeScript(ex, cheatScript(ex)).ok, false);
});

test('script: runs with different input catch a hard-coded answer without a variant (exec, stdin)', () => {
  const ex = fx('fx-script-greet');
  assert.deepEqual(scriptCommands(ex).map((r) => r.cmd), ['./hello.sh', './hello.sh']);
  const g = gradeScript(ex, ex.solution);
  assert.equal(g.ok, true);
  assert.equal(g.runs[0].cmd, 'chmod +x hello.sh', 'exec: the runner makes it executable first');
  assert.deepEqual(g.sh.runs.map((r) => r.out), ['Hello, Ada!\n', 'Hello, Linus!\n']);
  assert.equal(gradeScript(ex, '#!/bin/bash\necho "Hello, Linus!"\n').ok, false);
  assert.equal(gradeScript(ex, cheatScript(ex)).ok, false);
  assert.equal(gradeScript(ex, ex.starter).ok, false);
});

test('script: runs quote their arguments; errors and exit codes reach the checks', () => {
  const ex = { file: 'args.sh', setup: () => {}, runs: [{ args: ['two words', 'x'] }, { args: [] }], check: () => true };
  assert.deepEqual(scriptCommands(ex).map((r) => r.cmd), ["bash args.sh 'two words' x", 'bash args.sh']);
  const sh = freshShell(null);
  runScript(sh, ex, 'echo "$# [$1]"\n[ $# -gt 0 ] || { echo "usage: $0 NAME" >&2; exit 1; }\n');
  assert.deepEqual(sh.runs.map((r) => [r.out, r.code]), [['2 [two words]\n', 0], ['0 []\n', 1]]);
  assert.equal(runErr(sh), 'usage: args.sh NAME');
  assert.equal(runCode(sh, 0), 0);
  // a syntax error: what ran before it, then bash's two error lines, status 2
  runScript(sh, { ...ex, runs: [{}] }, 'echo start\nif [ -f x ]\n  echo no\nfi\n');
  assert.equal(runOut(sh), 'start');
  assert.equal(runErr(sh), "args.sh: line 4: syntax error near unexpected token `fi'\nargs.sh: line 4: `fi'");
  assert.equal(runCode(sh), 2);
  // read -p prints no prompt when the input is piped, as in bash
  runScript(sh, { ...ex, runs: [{ stdin: 'Bo\n' }] }, 'read -p "Name? " n\necho "Hi $n"\n');
  assert.equal(runOut(sh), 'Hi Bo');
  assert.equal(runErr(sh), '');
});
